wr('chapter24-source-check-01.json',{'range':'1–16','source':'https://fr.wikisource.org/wiki/Essais/Livre_I/Chapitre_25','decisions':[{'slot':1,'decision':'Jealous of honour means protective, not envious; childhood reaction irritation not mere wonder.'},{'slot':5,'decision':'Deliberate macaronic Latin preserved, matches French witness, not normalized as corruption.'},{'slot':8,'decision':'Ironic readiness restored; philosophers despise boaster because he lacks universal perspective, not philosophers themselves lacking it.'},{'slot':9,'decision':'Discours philosophical ideas governing life, not antique diction; corrected English.'},{'slot':12,'decision':'Restored donkey-drivers image; Danish kloge men ikke kloge repaired philosophical wisdom/practical prudence distinction.'},{'slot':16,'decision':'Latin apud alios ... secum means before others / with themselves, not learned from others/from themselves. Both corrected.'}]})
